"""AI Assistant Page view for Invito AI (Powered by Gemini 3.8 Flash)."""
import streamlit as st
from config.settings import DEFAULT_MODEL
from core.ai_service import (
    is_api_key_configured,
    stream_ai_chat,
    extract_card_json,
)
from core.file_parser import parse_uploaded_file
from ui.components import render_top_navbar


def apply_ai_json_to_card(data: dict):
    """Imports structured card parameters generated by the AI directly into active card state."""
    for key, val in data.items():
        if val is None:
            continue
        if key in ["bg_color", "primary_color", "text_color"]:
            st.session_state.card_theme[key] = val
            if key == "bg_color":
                st.session_state.card_theme["card_bg_gradient"] = f"linear-gradient(145deg, {val} 0%, #1A1A1A 100%)"
        elif key in st.session_state.card_data:
            st.session_state.card_data[key] = str(val)
        else:
            st.session_state.card_data[key] = str(val)

    st.toast("🎉 AI details applied to your invitation card canvas!", icon="✨")


def render_ai_chat_page():
    """Renders the AI Assistant chat page with multimodal reference uploads."""
    render_top_navbar("🤖 AI Assistant")
    st.markdown("## 🤖 Invito AI — Invitation Design Specialist")
    st.markdown(
        f"Powered by Google **`{DEFAULT_MODEL}`** with real-time streaming. "
        "Ask for custom invitation phrasing, rhyming verses, formal etiquette, or upload a photo or PDF of a sample card you love to replicate its aesthetic!"
    )

    # API Key Notice if missing
    if not is_api_key_configured():
        st.warning(
            "⚠️ **Gemini API Key Needed**: Please set your `GEMINI_API_KEY` inside the `.env` file in the project folder.\n\n"
            "```env\n"
            "GEMINI_API_KEY=your_gemini_api_key_here\n"
            "```\n"
            "Once saved, refresh this page to chat with the AI assistant. (Manual editing and template downloads remain fully functional!)"
        )

    # Initialize chat history if not present
    if "chat_messages" not in st.session_state:
        st.session_state.chat_messages = [
            {
                "role": "assistant",
                "content": (
                    "Hello! I am **Invito AI**, your personal luxury invitation designer and copywriter. 💌\n\n"
                    "Tell me about your upcoming event (occasion, couple/honoree names, theme, vibe, date, venue), "
                    "or upload sample photos/PDFs of cards you admire. I will write custom invitation copy "
                    "and generate a ready-to-import layout with a single click!"
                ),
            }
        ]

    # Multimodal Upload Section
    with st.expander("📎 Upload Sample Photos or PDF Card (Optional Reference)", expanded=False):
        c_up, c_prev = st.columns([1.3, 0.7])
        with c_up:
            sample_file = st.file_uploader(
                "Upload a sample invitation photo or PDF for the AI to analyze:",
                type=["png", "jpg", "jpeg", "webp", "pdf"],
                key="chat_multimodal_uploader",
                help="The AI will inspect the aesthetic, layout, colors, and wording of your uploaded sample.",
            )
        with c_prev:
            if sample_file:
                parsed = parse_uploaded_file(sample_file)
                st.session_state.uploaded_sample = parsed
                if parsed and parsed.preview_image:
                    st.image(parsed.preview_image, caption=f"Uploaded: {sample_file.name}", use_container_width=True)
                elif parsed and parsed.is_pdf:
                    st.success(f"📄 PDF extracted ({len(parsed.text_content)} chars)")
            else:
                st.session_state.uploaded_sample = None
                st.caption("No sample file currently attached.")

    # Suggestion Chips
    st.markdown("<div style='font-size: 0.85rem; color: #94A3B8; margin-top: 8px;'>Quick prompt ideas:</div>", unsafe_allow_html=True)
    chip_cols = st.columns(5)
    quick_prompts = [
        "💍 Ring Ceremony & Engagement for Rohan & Ananya",
        "👑 Royal Wedding for Aarav & Meera",
        "🎉 30th Birthday Bash with Cocktails",
        "🍼 Pastel Baby Shower for Elena",
        "💼 Black-Tie Executive Gala",
    ]
    prompt_to_send = None
    for i, col in enumerate(chip_cols):
        with col:
            if st.button(quick_prompts[i], key=f"chip_{i}", use_container_width=True):
                prompt_to_send = quick_prompts[i]

    # Display Chat History
    for idx, msg in enumerate(st.session_state.chat_messages):
        with st.chat_message(msg["role"], avatar="💌" if msg["role"] == "assistant" else "👤"):
            st.markdown(msg["content"])
            
            # If the assistant message contains card JSON, provide instant Apply button
            if msg["role"] == "assistant":
                card_json = extract_card_json(msg["content"])
                if card_json:
                    title_preview = card_json.get("title", "Generated Card")
                    event_preview = card_json.get("event_type", "")
                    with st.container():
                        st.markdown(
                            f"""
                            <div class="apply-card-box">
                                <div>
                                    <strong style="color: #D4AF37;">✨ Ready-To-Use Invitation Card Generated!</strong>
                                    <div style="font-size: 0.82rem; color: #E0E0E0; margin-top: 2px;">
                                        Title: <strong>{title_preview}</strong> {f'({event_preview})' if event_preview else ''}
                                    </div>
                                </div>
                            </div>
                            """,
                            unsafe_allow_html=True,
                        )
                        c_apply, c_studio = st.columns([1.2, 0.8])
                        with c_apply:
                            if st.button("✨ Apply These Details to My Card Canvas", key=f"apply_btn_{idx}", type="primary"):
                                apply_ai_json_to_card(card_json)
                                st.rerun()
                        with c_studio:
                            if st.button("Open Card Studio →", key=f"view_studio_btn_{idx}"):
                                st.switch_page("views/studio_view.py")

    # Chat Input Box
    user_input = st.chat_input("Ask Invito AI to create or customize an invitation...") or prompt_to_send

    if user_input:
        user_display = user_input
        attached_sample = st.session_state.get("uploaded_sample")
        if attached_sample:
            user_display += f"\n\n*(Attached reference: `{attached_sample.filename}`)*"

        st.session_state.chat_messages.append({"role": "user", "content": user_display})

        with st.chat_message("user", avatar="👤"):
            st.markdown(user_display)

        # Generate Assistant Streaming Response
        with st.chat_message("assistant", avatar="💌"):
            images = attached_sample.all_images if attached_sample and attached_sample.all_images else []
            doc_text = attached_sample.text_content if attached_sample else None

            # Stream response
            response_generator = stream_ai_chat(
                messages=st.session_state.chat_messages,
                attached_images=images,
                document_text=doc_text,
                model_name=DEFAULT_MODEL,
            )
            full_reply = st.write_stream(response_generator)

        # Save assistant message in history
        if full_reply:
            st.session_state.chat_messages.append({"role": "assistant", "content": full_reply})
            st.rerun()


if __name__ == "__main__" or True:
    render_ai_chat_page()
